<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import ResultList from './ResultList.vue';
import {type Context,type Limits,type ProgramEntry} from './api';
import {type Locale,formName} from './i18n';
const props=defineProps<{context?:Context;limits:Limits;entries:ProgramEntry[];locale:Locale;excludedConnections:string[];allowMixedDirections:boolean}>();
const emit=defineEmits<{adopt:[entries:ProgramEntry[]]}>();
const copy={
 en:{service_unavailable:'The service is unavailable. Your confirmed programs remain available. Start a new calculation when the service returns.',control_invalid:'This action is unavailable for the current calculation state.',pause:'Pause collection',continue:'Continue collection',paused:'Collection paused. Confirmed programs remain available.',pauseRequested:'Pause requested…',continueRequested:'Continue requested…',unknown:'Total unknown until collection finishes.',compare:'Compare',comparison:'Selected programs',calculate:'Calculate best program',cancel:'Cancel calculation',retry:'Retry connection',proving:'Proving the maximum…',collecting:'Maximum proved. Collecting alternatives…',completed:'All optimal compositions collected.',cancelled:'Calculation cancelled.',infeasible:'No compliant program exists for these constraints.',failed:'Calculation failed.',maximum:'Proved maximum BV',adopt:'Use this program',retained:'Retained',added:'Added',stale:'These results refer to earlier constraints. Calculate again to use a current program.',empty:'No proved program yet.',count:'Confirmed programs',requested:'Cancellation requested…',connection:'Connection interrupted. The current search identity is retained.',request_invalid:'Check the retained elements and planning restrictions.',unsupported_search:'This planning context does not support calculation.',internal_failure:'The program could not be verified. Start a new calculation.',search_capacity:'The service is busy. This calculation has not started.',session_unavailable:'This session is unavailable. Start a new calculation.',newCalculation:'Start a new calculation'},
 de:{service_unavailable:'Der Dienst ist nicht verfügbar. Bestätigte Programme bleiben erhalten. Nach der Wiederherstellung eine neue Berechnung starten.',control_invalid:'Diese Aktion ist im aktuellen Berechnungszustand nicht verfügbar.',pause:'Sammlung pausieren',continue:'Sammlung fortsetzen',paused:'Sammlung pausiert. Bestätigte Programme bleiben verfügbar.',pauseRequested:'Pause angefordert…',continueRequested:'Fortsetzung angefordert…',unknown:'Gesamtzahl bis zum Abschluss unbekannt.',compare:'Vergleichen',comparison:'Ausgewählte Programme',calculate:'Bestes Programm berechnen',cancel:'Berechnung abbrechen',retry:'Verbindung erneut versuchen',proving:'Maximum wird bewiesen…',collecting:'Maximum bewiesen. Alternativen werden gesammelt…',completed:'Alle optimalen Zusammenstellungen gesammelt.',cancelled:'Berechnung abgebrochen.',infeasible:'Für diese Vorgaben existiert kein regelkonformes Programm.',failed:'Berechnung fehlgeschlagen.',maximum:'Bewiesener maximaler Basiswert',adopt:'Dieses Programm übernehmen',retained:'Beibehalten',added:'Ergänzt',stale:'Diese Ergebnisse gehören zu früheren Vorgaben. Für ein aktuelles Programm erneut berechnen.',empty:'Noch kein bewiesenes Programm.',count:'Bestätigte Programme',requested:'Abbruch angefordert…',connection:'Verbindung unterbrochen. Die Identität der laufenden Suche bleibt erhalten.',request_invalid:'Beibehaltene Elemente und persönliche Vorgaben prüfen.',unsupported_search:'Dieser Planungskontext unterstützt keine Berechnung.',internal_failure:'Das Programm ließ sich nicht verifizieren. Neue Berechnung starten.',search_capacity:'Der Dienst ist ausgelastet. Diese Berechnung wurde nicht gestartet.',session_unavailable:'Diese Sitzung ist nicht verfügbar. Neue Berechnung starten.',newCalculation:'Neue Berechnung starten'},
 ru:{service_unavailable:'Сервис недоступен. Подтверждённые программы сохранены. Когда сервис станет доступен, запустите новый расчёт.',control_invalid:'Это действие недоступно в текущем состоянии расчёта.',pause:'Приостановить сбор',continue:'Продолжить сбор',paused:'Сбор приостановлен. Подтверждённые программы доступны.',pauseRequested:'Запрошена пауза…',continueRequested:'Запрошено продолжение…',unknown:'Общее число неизвестно до завершения сбора.',compare:'Сравнить',comparison:'Выбранные программы',calculate:'Рассчитать лучшую программу',cancel:'Отменить расчёт',retry:'Повторить подключение',proving:'Доказательство максимума…',collecting:'Максимум доказан. Поиск альтернатив…',completed:'Все оптимальные составы собраны.',cancelled:'Расчёт отменён.',infeasible:'Для этих ограничений нет программы, соответствующей правилам.',failed:'Расчёт завершился с ошибкой.',maximum:'Доказанная максимальная базовая стоимость',adopt:'Использовать эту программу',retained:'Сохранено',added:'Добавлено',stale:'Эти результаты относятся к прежним ограничениям. Запустите новый расчёт.',empty:'Доказанной программы пока нет.',count:'Подтверждённые программы',requested:'Запрошена отмена…',connection:'Соединение прервано. Идентификатор текущего поиска сохранён.',request_invalid:'Проверьте обязательные элементы и личные ограничения.',unsupported_search:'Расчёт недоступен для выбранных правил.',internal_failure:'Не удалось проверить программу. Запустите новый расчёт.',search_capacity:'Сервис занят. Этот расчёт не запущен.',session_unavailable:'Сессия недоступна. Запустите новый расчёт.',newCalculation:'Начать новый расчёт'}
};
const labels=computed(()=>copy[props.locale]);
const adoptionHint=computed(()=>({
 en:'Replaces interchangeable entries in My program. Required occurrences are kept. You can undo this before your next program or constraint change.',
 de:'Ersetzt austauschbare Einträge in Mein Programm. Erforderliche Vorkommen bleiben erhalten. Bis zur nächsten Programm- oder Vorgabenänderung kannst du die Übernahme rückgängig machen.',
 ru:'Заменяет заменяемые элементы в разделе «Моя программа». Обязательные элементы сохраняются. Отмена доступна до следующего изменения программы или ограничений.'
}[props.locale]));
interface Result {id:string;entries:{elementKey:string;code:string;requiredId:string|null}[];assessment:{totalHundredths:number;elements:{creditedHundredths:number|null;parts:{form:string;level:number|null}[]}[]}}
interface Identity {id:string;accessToken:string;requestId:string;revision:number}
interface Update {id:string;requestId:string;revision:number;status:'running'|'paused'|'completed'|'cancelled'|'infeasible'|'failed';phase:'proving'|'collecting'|'terminal';maximumBaseHundredths:number|null;confirmedCount:number;cursor:number;results:Result[];failure?:{code:string;entryIds?:string[]};controlRequested?:string}
const results=ref<Result[]>([]),update=ref<Update>(),stale=ref(false),busy=ref(false),connection=ref(false),problem=ref(''),cancelRequested=ref(false);
const selected=ref<string[]>([]);
const compared=computed(()=>results.value.filter(r=>selected.value.includes(r.id)));
const pendingControl=ref<{action:'pause'|'continue'|'cancel';commandId:string}>();
// A control or newer read supersedes every older in-flight status snapshot.
let pollSequence=0;
let generation=0,identity:Identity|undefined,cursor=0,timer:ReturnType<typeof setTimeout>|undefined;
let creation:{body:unknown;generation:number}|undefined;
function ordered(value:unknown):unknown {if(Array.isArray(value))return value.map(ordered);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,ordered(v)]));return value;}
// Whole-entry order, replaceable content, completeness and presentation do not
// alter this freely placed composition problem. Required occurrences keep IDs.
const signature=computed(()=>JSON.stringify(ordered({context:props.context,limits:props.limits,required:props.entries.filter(e=>e.retained).map(({id,elementKey})=>({id,elementKey})).sort((a,b)=>a.id.localeCompare(b.id)),excluded:[...props.excludedConnections].sort(),mixed:props.allowMixedDirections})));
async function request<T>(path:string,method='GET',body?:unknown,owner?:Identity):Promise<T>{const response=await fetch(path,{method,headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(owner?{Authorization:`Bearer ${owner.accessToken}`}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});if(!response.ok)throw new Error((await response.json().catch(()=>({code:'service_unavailable'}))).code);return response.json();}
function number(value:number|null|undefined){return value==null?'—':new Intl.NumberFormat(props.locale,{minimumFractionDigits:2,maximumFractionDigits:2}).format(value/100);}
function stopPolling(){pollSequence++;if(timer)clearTimeout(timer);timer=undefined;}
async function release(owner:Identity){try{await request(`/api/v1/searches/${owner.id}`,'DELETE',undefined,owner);}catch{/* The independent service lease reaches disconnected owners. */}}
function invalidate(){generation++;stopPolling();if(identity)void release(identity);identity=undefined;creation=undefined;busy.value=false;connection.value=false;cancelRequested.value=false;pendingControl.value=undefined;if(results.value.length||update.value?.maximumBaseHundredths!=null)stale.value=true;}
watch(signature,invalidate);
function failed(error:unknown){problem.value=error instanceof Error?error.message:'connection';connection.value=!(error instanceof Error)||error instanceof TypeError;if(!connection.value){busy.value=false;pendingControl.value=undefined;stopPolling();if(problem.value==='session_unavailable'){identity=undefined;creation=undefined;}}}
async function poll(own:number){if(!identity||own!==generation)return;stopPolling();const sequence=pollSequence,owner=identity;try{const next=await request<Update>(`/api/v1/searches/${owner.id}/updates?after=${cursor}&limit=100`,'GET',undefined,owner);if(own!==generation||sequence!==pollSequence||next.id!==owner.id||next.requestId!==owner.requestId||next.revision!==owner.revision)return;
 connection.value=false;problem.value='';update.value=next;cursor=next.cursor;const known=new Set(results.value.map(r=>r.id));for(const r of next.results)if(!known.has(r.id)){results.value.push(r);known.add(r.id);}busy.value=next.status==='running'||next.status==='paused';cancelRequested.value=next.controlRequested==='cancel';if(next.failure)problem.value=next.failure.code;
 if(busy.value||cursor<next.confirmedCount)timer=setTimeout(()=>poll(own),cursor<next.confirmedCount?0:1000);
 }catch(error){if(own===generation&&sequence===pollSequence)failed(error);}}
async function submit(){if(!creation)return;const current=creation;busy.value=true;connection.value=false;problem.value='';try{const owner=await request<Identity>('/api/v1/searches','POST',current.body);if(current.generation!==generation){void release(owner);return;}if(creation!==current)return;identity=owner;creation=undefined;results.value=[];selected.value=[];update.value=undefined;stale.value=false;cursor=0;void poll(generation);}catch(error){if(current.generation===generation){busy.value=false;failed(error);}}}
async function calculate(){if(busy.value)return;invalidate();if(!props.context)return;const own=generation;const input=JSON.parse(JSON.stringify({context:props.context,personalLimits:props.limits,requiredElements:props.entries.filter(e=>e.retained).map(({id,elementKey})=>({id,elementKey})),allowMixedDirections:props.allowMixedDirections,excludedConnections:props.excludedConnections}));busy.value=true;problem.value='';try{const namespace=await request<{creationNamespace:string}>('/api/v1/searches/identity');if(own!==generation)return;const bytes=crypto.getRandomValues(new Uint8Array(32));const retryKey=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');creation={generation:own,body:JSON.parse(JSON.stringify({creationKey:`${namespace.creationNamespace}:${retryKey}`,requestId:crypto.randomUUID(),revision:own,...input}))};await submit();}catch(error){if(own===generation){busy.value=false;failed(error);}}}
async function retry(){if(pendingControl.value)await sendControl();else if(creation)await submit();else if(identity)await poll(generation);else await calculate();}
async function control(action:'pause'|'continue'|'cancel'){if(action!=='cancel'&&(pendingControl.value||update.value?.controlRequested))return;pendingControl.value={action,commandId:crypto.randomUUID()};await sendControl();}
async function sendControl(){if(!identity||!pendingControl.value)return;stopPolling();const own=generation,owner=identity,command=pendingControl.value;try{await request(`/api/v1/searches/${owner.id}/${command.action}`,'POST',{commandId:command.commandId},owner);if(own===generation&&pendingControl.value===command){pendingControl.value=undefined;void poll(own);}}catch(error){if(own===generation&&pendingControl.value===command)failed(error);}}
function entryName(result:Result,index:number){return result.assessment.elements[index]?.parts.map(part=>`${formName(props.locale,part.form)}${part.level==null?'':` ${part.level===0?'B':part.level}`}`).join(' + ');}
function adopt(result:Result){if(stale.value)return;emit('adopt',result.entries.map(e=>({id:e.requiredId??crypto.randomUUID(),elementKey:e.elementKey,code:e.code,retained:e.requiredId!==null})));}
const stateMessage=computed(()=>{if(problem.value==='session_unavailable')return labels.value.session_unavailable;const s=update.value;if(!s||stale.value&&busy.value)return busy.value?labels.value.proving:labels.value.empty;if(s.status==='running')return labels.value[s.phase==='collecting'?'collecting':'proving'];return labels.value[s.status];});
const errorMessage=computed(()=>{const code=problem.value;if(['invalid_command','invalid_transition','command_conflict'].includes(code))return labels.value.control_invalid;if(['invalid_cursor','creation_conflict','invalid_entry_id','malformed_json'].includes(code))return labels.value.request_invalid;return labels.value[code as keyof typeof copy.en]??(connection.value?labels.value.connection:labels.value.service_unavailable);});
function pagehide(){const owner=identity;generation++;stopPolling();identity=undefined;creation=undefined;pendingControl.value=undefined;busy.value=false;connection.value=false;if(owner){problem.value='session_unavailable';void fetch(`/api/v1/searches/${owner.id}`,{method:'DELETE',headers:{Authorization:`Bearer ${owner.accessToken}`},keepalive:true}).catch(()=>{});}}
onMounted(()=>window.addEventListener('pagehide',pagehide));
onBeforeUnmount(()=>{window.removeEventListener('pagehide',pagehide);invalidate();});
defineExpose({calculate,busy});
</script>
<template>
<div class="planning-search">
 <div class="search-actions">
 <button data-testid="calculate" :disabled="!context||busy" @click="calculate">{{labels.calculate}}</button>
 <button v-if="busy&&identity" :disabled="cancelRequested||pendingControl?.action==='cancel'" @click="control('cancel')">{{labels.cancel}}</button>
 <button v-if="update?.phase==='collecting'&&busy" data-testid="collection-control" :aria-disabled="!!pendingControl||!!update.controlRequested" @click="control(update.status==='paused'?'continue':'pause')">{{update.status==='paused'?labels.continue:labels.pause}}</button>
 </div>
 <div role="status" aria-live="polite"><p>{{stateMessage}}</p><p v-if="update?.controlRequested==='pause'||pendingControl?.action==='pause'">{{labels.pauseRequested}}</p><p v-if="update?.controlRequested==='continue'||pendingControl?.action==='continue'">{{labels.continueRequested}}</p><p v-if="(cancelRequested||pendingControl?.action==='cancel')&&busy">{{labels.requested}}</p><p v-if="update?.maximumBaseHundredths!=null" data-testid="search-maximum">{{labels.maximum}}: <strong>{{number(update.maximumBaseHundredths)}}</strong></p><p v-if="update">{{labels.count}}: {{update.confirmedCount}}<span v-if="update.status!=='completed'"> · {{labels.unknown}}</span></p></div>
 <p v-if="connection||problem" role="alert">{{errorMessage}} <button v-if="connection" @click="retry">{{labels.retry}}</button></p>
 <ul v-if="update?.failure?.entryIds?.length"><li v-for="id in update.failure.entryIds" :key="id">{{labels.retained}}: {{entries.find(e=>e.id===id)?.code??id}}</li></ul>
 <p v-if="stale" data-testid="search-stale" role="status">{{labels.stale}}</p>
 <section v-if="compared.length" :aria-label="labels.comparison" data-testid="program-comparison"><h3>{{labels.comparison}}</h3><ResultList :results="compared" :locale="locale" v-slot="{result}"><table><tbody><tr><th scope="row">{{labels.compare}} {{results.indexOf(result)+1}}</th><td>{{number(result.assessment.totalHundredths)}}</td><td><ul><li v-for="(entry,index) in result.entries" :key="index"><code>{{entry.code}}</code> {{entryName(result,index)}} · {{entry.requiredId?labels.retained:labels.added}} · {{number(result.assessment.elements[index]?.creditedHundredths)}}</li></ul></td></tr></tbody></table></ResultList></section>
 <ResultList :results="results" :locale="locale" v-slot="{result,index:resultIndex}"><label><input v-model="selected" type="checkbox" :value="result.id"> {{labels.compare}} {{resultIndex+1}}</label> <strong>{{number(result.assessment.totalHundredths)}}</strong><ul><li v-for="(entry,index) in result.entries" :key="index"><code>{{entry.code}}</code> <span>{{entryName(result,index)}}</span> · {{entry.requiredId?labels.retained:labels.added}} · {{number(result.assessment.elements[index]?.creditedHundredths)}}</li></ul><p :id="`adoption-${result.id}`">{{adoptionHint}}</p><button data-testid="adopt-result" :aria-describedby="`adoption-${result.id}`" :disabled="stale" @click="adopt(result)">{{labels.adopt}}</button></ResultList>
</div>
</template>
